INSERT INTO public.products (category_id, name, slug, short_description, description, price_ngn, compare_at_price_ngn, deposit_percent, stock, is_active, is_featured, is_subscription, subscription_interval, images, specs) VALUES ((SELECT id FROM public.product_categories WHERE slug='cctv-cameras'), 'Fortress 8MP Motorised Zoom', 'fortress-8mp-motorised-zoom', 'Zoom remotely from your app — no more ladder trips to adjust the lens.', 'A motorised 2.8–12mm lens you control from the DVR or app. Set the frame from your desk, zoom in during an incident review, then zoom back out. 8MP resolution means you keep detail even fully zoomed.', 145000.0, NULL, 50, 25, true, true, false, NULL, ARRAY[]::text[], '{"tech": {"lens": "2.8–12mm motorised", "power": "12V DC", "ip_rating": "IP67", "resolution": "8MP 4K", "night_vision": "50m EXIR"}, "features": ["8MP 4K UHD resolution", "50m EXIR night vision", "2.8–12mm motorised zoom lens", "Remote zoom & focus from app", "IP67 metal housing with sunshield"], "use_case": "Mission-critical mounts on high poles or rooftops where physically adjusting the lens is inconvenient.", "hook_line": "Zoom remotely from your app — no more ladder trips to adjust the lens.", "price_usd": 105, "image_brief": "Large grey bullet camera high on a metal pole overlooking a compound entrance.", "recommended_for": "Enterprise"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
